import {NextResponse} from "next/server";import bcrypt from "bcryptjs";import {prisma} from "@mysme/core/db";import {COOKIE_NAME,createToken} from "@mysme/core/auth";
export async function POST(request){const {email,password}=await request.json();const user=await prisma.user.findUnique({where:{email:String(email).toLowerCase().trim()}});if(!user?.passwordHash||user.userRole!=="seller"||!(await bcrypt.compare(password,user.passwordHash)))return NextResponse.json({error:"Invalid seller credentials"},{status:401});const response=NextResponse.json({ok:true});response.cookies.set(COOKIE_NAME,await createToken(user.id),{httpOnly:true,sameSite:"lax",path:"/",maxAge:604800});return response}
